#!/bin/bash

mariadb -u root -p${MARIADB_ROOT_PASSWORD} -e "CREATE DATABASE `$DATABASE_NAME` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci */;GRANT CREATE, ALTER, CREATE VIEW, DELETE, INDEX, INSERT, REFERENCE, SELECT, SHOW VIEW, UPDATE ON $DATABASE_NAME.* TO '$DATABASE_USER'@'%';"